DELETE FROM OFT_MEAL_PLAN_ENTRY
WHERE USER_NO = #{userNo}
  AND ENTRY_NO = #{entryNo}

DELETE FROM OFT_MEAL_PLAN_ENTRY_INGREDIENT
WHERE ENTRY_NO IN (
    SELECT ENTRY_NO
    FROM OFT_MEAL_PLAN_ENTRY
    WHERE USER_NO = #{userNo}
      AND PLAN_NO = #{planNo}
)

